    for (int i = 0; i < 8; i++) {
        int global_m = block_m + threadIdx.y * 8 + i;
        if (global_m >= m) continue;

        #pragma unroll
        for (int j = 0; j < 8; j++) {
            int global_n = block_n + threadIdx.x * 8 + j;
            if (global_n >= n) continue;

            C_batch[global_m * n + global_n] = acc[i][j];
        }
    }
